CREATE TABLE prescriptions (id VARCHAR(80) PRIMARY KEY, tenant_id UUID NOT NULL, examination_id VARCHAR(80) NOT NULL REFERENCES examinations(id) ON DELETE RESTRICT, patient_id UUID NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, veterinarian_id VARCHAR(100) NOT NULL, notes TEXT, status VARCHAR(30) NOT NULL, prescribed_at TIMESTAMPTZ(6) NOT NULL, expires_at TIMESTAMPTZ(6) NOT NULL, dispensed_at TIMESTAMPTZ(6), dispensed_by UUID, cancel_reason TEXT, created_at TIMESTAMPTZ(6) NOT NULL, updated_at TIMESTAMPTZ(6) NOT NULL);
CREATE TABLE prescription_items (id BIGSERIAL PRIMARY KEY, prescription_id VARCHAR(80) NOT NULL REFERENCES prescriptions(id) ON DELETE RESTRICT, drug_name VARCHAR(200) NOT NULL, dosage VARCHAR(100) NOT NULL, frequency VARCHAR(30) NOT NULL, custom_frequency VARCHAR(200), duration_days INT NOT NULL, route VARCHAR(30) NOT NULL, instructions TEXT, product_id VARCHAR(100), dispensed_quantity VARCHAR(30), dispensed_lot_id VARCHAR(100));
CREATE INDEX prescriptions_tenant_patient_prescribed_idx ON prescriptions(tenant_id,patient_id,prescribed_at);
CREATE INDEX prescription_items_prescription_idx ON prescription_items(prescription_id);
ALTER TABLE prescriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY prescriptions_tenant_isolation ON prescriptions USING (current_setting('app.is_superadmin',true)='true' OR tenant_id::text=current_setting('app.tenant_id',true)) WITH CHECK (current_setting('app.is_superadmin',true)='true' OR tenant_id::text=current_setting('app.tenant_id',true));
ALTER TABLE prescription_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY prescription_items_tenant_isolation ON prescription_items USING (EXISTS (SELECT 1 FROM prescriptions p WHERE p.id=prescription_id AND (current_setting('app.is_superadmin',true)='true' OR p.tenant_id::text=current_setting('app.tenant_id',true))));
